import math
import statistics
# pytest cannot load on this page: compare floats with math.isclose


# src/risk.py
def simple_returns(closes):
    return [b / a - 1 for a, b in zip(closes, closes[1:])]


def annualised_vol(returns):
    return statistics.stdev(returns) * math.sqrt(252)


def max_drawdown(closes):
    peak, worst = closes[0], 0.0
    for c in closes:
        peak = max(peak, c)
        worst = max(worst, (peak - c) / peak)
    return worst


# tests/test_risk.py
def test_simple_returns():
    r = simple_returns([100.00, 104.00, 101.92])
    assert len(r) == 2
    assert math.isclose(r[0], 0.04) and math.isclose(r[1], -0.02)


def test_annualised_vol():
    # mean 0, squared distances 0.0002 over n - 1 = 1, times 252
    assert math.isclose(annualised_vol([0.01, -0.01]), math.sqrt(0.0002 * 252))


def test_max_drawdown():
    assert math.isclose(max_drawdown([100.00, 120.00, 90.00]), 0.25)  # trough last
    assert max_drawdown([80.00, 100.00, 120.00]) == 0.0               # only rises
